// The user id is the connection's, never the frame's: validation has already dropped any the client sent.
async function handleListSessions(
  ws: WebSocket,
  session: ChatSession,
  sessionStore: SessionStore | undefined,
  {limit, before}: ListSessionsMessage
): Promise<void> {
  try {
    const summaries = (await sessionStore?.listFor?.(session.userId, {limit, before})) ?? [];
    sendJson(ws, {
      type: 'session_list',
      sessions: summaries.map(summary => ({
        ...summary,
        createdAt: summary.createdAt.toISOString(),
        updatedAt: summary.updatedAt.toISOString(),
      })),
    });
  } catch (error) {
    log.error('ws', 'listing sessions failed', {
      userId: session.userId,
      error: error instanceof Error ? error.message : 'Unknown error',
    });
    sendError(ws, ErrorCodes.SERVER_ERROR, 'Failed to list sessions');
  }
}""")
